def is_simple_power(x, n):
    """Return True if x is a simple power of n (n**k == x for some integer k)."""
    if x == 1:
        return True
    if n == 1:
        return x == 1
    if n == 0:
        return x == 0
    if n == -1:
        return x in (-1, 1)

    power = n
    while abs(power) < abs(x):
        power *= n
    return power == x
```

